/**
 * Create a non-interleaved version of a buffer attribute.
 *
 * @param {THREE.BufferAttribute|THREE.InterleavedBufferAttribute} attribute - Source attribute.
 * @returns {THREE.BufferAttribute|THREE.InstancedBufferAttribute} New attribute.
 */
export function deinterleaveAttribute(attribute: THREE.BufferAttribute | THREE.InterleavedBufferAttribute): THREE.BufferAttribute | THREE.InstancedBufferAttribute;
/**
 * Add a physics body from a mesh. For BatchedMesh/InstancedMesh without `instanceMatrixIndex`,
 * automatically batches ALL instances and returns an array of API objects.
 *
 * @param {Object} physicsApi - The physics worker API (physics.api)
 * @param {BodyType} type - Body type from BodyType enum: BodyType.STATIC, BodyType.DYNAMIC, BodyType.KINEMATIC, BodyType.ZONE
 * @param {THREE.Mesh|THREE.Group|THREE.InstancedMesh|THREE.BatchedMesh} meshOrCollideBox - The mesh, group, instanced mesh, or batched mesh to create physics for
 * @param {Object} [properties={}] - Physics properties
 * @param {number} [properties.friction] - Surface friction coefficient
 * @param {number} [properties.mass] - Body mass (for dynamic bodies)
 * @param {number} [properties.pFrom] - Platform start position (for moving platforms)
 * @param {number} [properties.pTo] - Platform end position (for moving platforms)
 * @param {Object} [bodyProps={}] - Body properties
 * @param {number} [bodyProps.capsuleRadius] - Capsule collision radius (for dynamic/kinematic)
 * @param {number} [bodyProps.capsuleLength] - Capsule collision length (for dynamic/kinematic)
 * @param {Array<number>} [bodyProps.initialPosition] - Initial position [x, y, z]
 * @param {Object} [options={}] - Optional settings
 * @param {THREE.Mesh} [options.hitbox] - Custom hitbox mesh (overrides auto-generated collision)
 * @param {THREE.Material} [options.debugMaterial] - Material for debug visualization
 * @param {number} [options.side] - BVH side (e.g., THREE.DoubleSide)
 * @param {number} [options.instanceMatrixIndex] - For InstancedMesh/BatchedMesh: which instance to use. If omitted, ALL instances are batched automatically.
 * @param {THREE.BufferGeometry} [options.sourceGeometry] - For BatchedMesh single instance: original geometry (skips extraction)
 * @param {Object} [options.sourceGeometries] - For BatchedMesh batch mode: map of geometryId -> BufferGeometry
 * @param {Function} [options.customGeometryToBVHScript] - Custom geometry processing function
 * @returns {Promise<Object|Array<Object>>} The body API object(s). Returns array for batched BatchedMesh/InstancedMesh (when no instanceMatrixIndex provided).
 *   - `index` {number} - Body index in the physics system
 *   - `type` {string} - Body type ('static', 'dynamic', 'kinematic', 'zone')
 *   - `entity` {THREE.Object3D} - The mesh/entity passed in
 *   - `collideBox` {THREE.Mesh} - The collision mesh (may differ from entity)
 *   - `instanceIndex` {number} - (BatchedMesh/InstancedMesh only) The instance index within the mesh
 *
 * @example
 * ```javascript
 * import { BodyType } from '@three-blocks/pro';
 *
 * // Static body with friction
 * const api = await addBody(physics.api, BodyType.STATIC, groundMesh, { friction: 0.8 });
 *
 * // Dynamic body (player)
 * const api = await addBody(physics.api, BodyType.DYNAMIC, playerMesh, { mass: 1.5 }, {
 *   capsuleRadius: 0.5,
 *   capsuleLength: 1.0,
 *   initialPosition: [0, 5, 0]
 * });
 *
 * // InstancedMesh - auto-batch ALL instances (returns array)
 * const apis = await addBody(physics.api, BodyType.STATIC, instancedMesh, { friction: 0.5 });
 * ```
 *
 * @short Create a physics body from a Three.js mesh
 * @category Helpers
 * @private
 */
export function addBody(physicsApi: any, type: BodyType, meshOrCollideBox: THREE.Mesh | THREE.Group | THREE.InstancedMesh | THREE.BatchedMesh, properties?: {
    friction?: number;
    mass?: number;
    pFrom?: number;
    pTo?: number;
}, bodyProps?: {
    capsuleRadius?: number;
    capsuleLength?: number;
    initialPosition?: Array<number>;
}, options?: {
    hitbox?: THREE.Mesh;
    debugMaterial?: THREE.Material;
    side?: number;
    instanceMatrixIndex?: number;
    sourceGeometry?: THREE.BufferGeometry;
    sourceGeometries?: any;
    customGeometryToBVHScript?: Function;
}): Promise<any | Array<any>>;
/**
 * Add multiple physics bodies in a single batch operation.
 * Significantly faster than calling addBody multiple times for many different meshes.
 *
 * **Note:** For InstancedMesh/BatchedMesh where all instances share the same properties,
 * use `addBody()` without `instanceMatrixIndex` instead - it auto-batches all instances.
 * Use `addBodies()` when you have many different meshes to add.
 *
 * @param {Object} physicsApi - The physics worker API (physics.api)
 * @param {BodyType} type - Body type from BodyType enum: BodyType.STATIC, BodyType.DYNAMIC, BodyType.KINEMATIC, BodyType.ZONE
 * @param {Array<Object>} bodiesConfig - Array of body configurations
 * @param {THREE.Mesh|THREE.Group} bodiesConfig[].mesh - The mesh to create physics for
 * @param {Object} [bodiesConfig[].properties] - Physics properties
 * @param {number} [bodiesConfig[].properties.friction] - Surface friction coefficient
 * @param {number} [bodiesConfig[].properties.mass] - Body mass (for dynamic bodies)
 * @param {Object} [bodiesConfig[].bodyProps] - Body properties
 * @param {number} [bodiesConfig[].bodyProps.capsuleRadius] - Capsule collision radius
 * @param {number} [bodiesConfig[].bodyProps.capsuleLength] - Capsule collision length
 * @param {Array<number>} [bodiesConfig[].bodyProps.initialPosition] - Initial position [x, y, z]
 * @param {Object} [bodiesConfig[].options] - Optional settings
 * @param {THREE.Mesh} [bodiesConfig[].options.hitbox] - Custom hitbox mesh
 * @param {number} [bodiesConfig[].options.side] - BVH side (e.g., THREE.DoubleSide)
 * @param {Function} [bodiesConfig[].options.customGeometryToBVHScript] - Custom geometry processing
 * @returns {Promise<Array<Object>>} Array of body API objects, each containing:
 *   - `index` {number} - Body index in the physics system
 *   - `type` {string} - Body type ('static', 'dynamic', 'kinematic', 'zone')
 *   - `entity` {THREE.Object3D} - The mesh/entity passed in
 *   - `collideBox` {THREE.Mesh} - The collision mesh
 *
 * @example
 * ```javascript
 * import { BodyType } from '@three-blocks/pro';
 *
 * // Add many different meshes in one batch
 * const configs = meshes.map(mesh => ({
 *   mesh,
 *   properties: { friction: 0.5 },
 * }));
 * const apis = await addBodies(physics.api, BodyType.STATIC, configs);
 * ```
 *
 * @short Batch-add multiple physics bodies for maximum performance
 * @category Helpers
 * @private
 */
export function addBodies(physicsApi: any, type: BodyType, bodiesConfig: Array<any>): Promise<Array<any>>;
